fn solve(a:&[i64],out:&mut [i64])->usize{if a.len()<=1{if !a.is_empty(){out[0]=a[0];}return a.len();}let pivot=a[0];let mut best=[0i64;10];let mut bl=0;let mut i=1;while i<a.len(){if a[i]<pivot{let tail:Vec<i64>=a[i+1..].iter().copied().filter(|&x|x>=a[i]).collect();let mut cand=[0i64;10];let sl=solve(&tail,&mut cand[1..]);cand[0]=a[i];if sl+1>bl{bl=sl+1;best[0]=cand[0];i=1;while i<bl{best[i]=cand[i];i+=1;}}}i+=1;}let tail:Vec<i64>=a[1..].iter().copied().filter(|&x|x>=pivot).collect();let mut cand=[0i64;10];let sl=solve(&tail,&mut cand[1..]);cand[0]=pivot;if sl+1>bl{bl=sl+1;best[..bl].copy_from_slice(&cand[..bl]);}out[..bl].copy_from_slice(&best[..bl]);bl}
#[no_mangle]
pub extern "C" fn longest_subsequence(v:*const i64,n:usize)->i64{if n<2||n>11||v.is_null(){return -1;}let s=unsafe{std::slice::from_raw_parts(v,n)};let k=s[0];if k<1||k>10||n!=k as usize+1||s[1..].iter().any(|&x|!(-10..=10).contains(&x)){return -1;}let mut out=[0i64;10];let len=solve(&s[1..],&mut out);out[..len].iter().fold(len as i64,|r,&x|r*21+x+10)}
